class Solution { fun rearrangeBarcodes(barcodes:IntArray):IntArray{val count=barcodes.toList().groupingBy{it}.eachCount();val heap=java.util.PriorityQueue<IntArray>{a,b->if(a[0]!=b[0])b[0]-a[0] else a[1]-b[1]};for((value,frequency) in count)heap.add(intArrayOf(frequency,value));val answer=IntArray(barcodes.size);var previous:IntArray?=null;for(i in answer.indices){val current=heap.remove();answer[i]=current[1];current[0]--;if(previous!=null&&previous[0]>0)heap.add(previous);previous=current};return answer} }
